events=[]
class Mapping:
 def keys(self):
  events.append('keys')
  def produce():
   for key in ['a','b']:
    events.append('key:'+key)
    yield key
  return produce()
 def __getitem__(self,key):
  events.append('get:'+key)
  return key.upper()
d={**Mapping()}
print(d,events)

