class Key:
 def __hash__(self): return 1
 def __eq__(self,other): return isinstance(other,Key)
original=Key()
replacement=Key()
d={original:1,**{replacement:2}}
s={original,*[replacement]}
print(len(d),next(iter(d)) is original,d[replacement],len(s))

def combine(base):
 prefix=3
 result={**base,'marker':prefix}
 return result,locals()['prefix']
print(combine({'a':1}))

def g():
 result={**(yield {'a':1}),'x':2}
 yield result
iterator=g()
print(next(iterator))
print(iterator.send({'b':3}))
def h():
 result={0,*(yield [1]),2}
 yield result
iterator=h()
print(next(iterator))
print(sorted(iterator.send((3,4))))

